def f(g):
    h=len(g); w=len(g[0]); out=[row[:] for row in g]
    # full uniform rows/cols
    for i in range(h):
        if len(set(g[i]))==1 and g[i][0]!=0:
            out[i]=[2]*w
    for j in range(w):
